// src/modules/care/care.repository.ts
import { runQueryWithTenant, runQueriesWithTenant } from '@core/database/pool';
import type { CareSessionRow, CareMessageRow } from './care.types';

export class CareRepository {
  /**
   * Busca sessão por ID
   */
  async findSessionById(tenantId: string, sessionId: string): Promise<CareSessionRow | null> {
    const row = await runQueryWithTenant<CareSessionRow>(
      tenantId,
      `
      SELECT care_session_id, tenant_id, global_user_id, target_global_user_id, target_company_id, last_message, state, context, created_at, updated_at
      FROM care_sessions
      WHERE care_session_id = $1
      LIMIT 1
      `,
      [sessionId]
    );

    return row || null;
  }

  /**
   * Busca sessão ativa por usuário e target
   */
  async findActiveSession(
    tenantId: string,
    globalUserId: string,
    targetGlobalUserId?: string | null,
    targetCompanyId?: string | null
  ): Promise<CareSessionRow | null> {
    let query = `
      SELECT care_session_id, tenant_id, global_user_id, target_global_user_id, target_company_id, last_message, state, context, created_at, updated_at
      FROM care_sessions
      WHERE global_user_id = $1
    `;

    const params: any[] = [globalUserId];

    if (targetGlobalUserId) {
      query += ` AND target_global_user_id = $2`;
      params.push(targetGlobalUserId);
    } else if (targetCompanyId) {
      query += ` AND target_company_id = $2`;
      params.push(targetCompanyId);
    } else {
      query += ` AND target_global_user_id IS NULL AND target_company_id IS NULL`;
    }

    query += ` ORDER BY updated_at DESC LIMIT 1`;

    const row = await runQueryWithTenant<CareSessionRow>(tenantId, query, params);

    return row || null;
  }

  /**
   * Cria uma nova sessão
   */
  async createSession(data: {
    tenantId: string;
    globalUserId: string;
    targetGlobalUserId?: string | null;
    targetCompanyId?: string | null;
    state: any;
    context: any;
  }): Promise<CareSessionRow> {
    const row = await runQueryWithTenant<CareSessionRow>(
      data.tenantId,
      `
      INSERT INTO care_sessions (tenant_id, global_user_id, target_global_user_id, target_company_id, state, context)
      VALUES ($1, $2, $3, $4, $5, $6)
      RETURNING care_session_id, tenant_id, global_user_id, target_global_user_id, target_company_id, last_message, state, context, created_at, updated_at
      `,
      [
        data.tenantId,
        data.globalUserId,
        data.targetGlobalUserId ?? null,
        data.targetCompanyId ?? null,
        JSON.stringify(data.state),
        JSON.stringify(data.context),
      ]
    );

    if (!row) {
      throw new Error('Falha ao criar sessão');
    }

    return row;
  }

  /**
   * Atualiza estado e contexto da sessão
   */
  async updateSession(
    tenantId: string,
    sessionId: string,
    updates: {
      lastMessage?: string;
      state?: any;
      context?: any;
    }
  ): Promise<CareSessionRow | null> {
    const updatesList: string[] = [];
    const params: any[] = [];
    let paramIndex = 1;

    if (updates.lastMessage !== undefined) {
      updatesList.push(`last_message = $${paramIndex}`);
      params.push(updates.lastMessage);
      paramIndex++;
    }

    if (updates.state !== undefined) {
      updatesList.push(`state = $${paramIndex}`);
      params.push(JSON.stringify(updates.state));
      paramIndex++;
    }

    if (updates.context !== undefined) {
      updatesList.push(`context = $${paramIndex}`);
      params.push(JSON.stringify(updates.context));
      paramIndex++;
    }

    if (updatesList.length === 0) {
      return await this.findSessionById(tenantId, sessionId);
    }

    params.push(sessionId);

    const row = await runQueryWithTenant<CareSessionRow>(
      tenantId,
      `
      UPDATE care_sessions
      SET ${updatesList.join(', ')}, updated_at = now()
      WHERE care_session_id = $${paramIndex}
      RETURNING care_session_id, tenant_id, global_user_id, target_global_user_id, target_company_id, last_message, state, context, created_at, updated_at
      `,
      params
    );

    return row || null;
  }

  /**
   * Busca mensagens de uma sessão
   */
  async findMessagesBySession(
    tenantId: string,
    sessionId: string,
    options: { limit?: number; offset?: number } = {}
  ): Promise<{ rows: CareMessageRow[]; total: number }> {
    const { limit = 100, offset = 0 } = options;

    const rows = await runQueriesWithTenant<CareMessageRow>(
      tenantId,
      `
      SELECT message_id, care_session_id, is_from_user, content, intent, parameters, ai_reasoning, created_at
      FROM care_messages
      WHERE care_session_id = $1
      ORDER BY created_at ASC
      LIMIT $2 OFFSET $3
      `,
      [sessionId, limit, offset]
    );

    // Contar total
    const countRow = await runQueryWithTenant<{ total: string }>(
      tenantId,
      `
      SELECT COUNT(*) as total
      FROM care_messages
      WHERE care_session_id = $1
      `,
      [sessionId]
    );

    return {
      rows,
      total: countRow ? Number(countRow.total) : 0,
    };
  }

  /**
   * Cria uma nova mensagem
   */
  async createMessage(data: {
    tenantId: string;
    careSessionId: string;
    isFromUser: boolean;
    content: string;
    intent?: string | null;
    parameters?: any;
    aiReasoning?: any;
  }): Promise<CareMessageRow> {
    const row = await runQueryWithTenant<CareMessageRow>(
      data.tenantId,
      `
      INSERT INTO care_messages (care_session_id, is_from_user, content, intent, parameters, ai_reasoning)
      VALUES ($1, $2, $3, $4, $5, $6)
      RETURNING message_id, care_session_id, is_from_user, content, intent, parameters, ai_reasoning, created_at
      `,
      [
        data.careSessionId,
        data.isFromUser,
        data.content,
        data.intent ?? null,
        data.parameters ? JSON.stringify(data.parameters) : null,
        data.aiReasoning ? JSON.stringify(data.aiReasoning) : null,
      ]
    );

    if (!row) {
      throw new Error('Falha ao criar mensagem');
    }

    return row;
  }

  /**
   * Busca sessões de um usuário
   */
  async findSessionsByUser(
    tenantId: string,
    globalUserId: string,
    options: { limit?: number; offset?: number } = {}
  ): Promise<{ rows: CareSessionRow[]; total: number }> {
    const { limit = 50, offset = 0 } = options;

    const rows = await runQueriesWithTenant<CareSessionRow>(
      tenantId,
      `
      SELECT care_session_id, tenant_id, global_user_id, target_global_user_id, target_company_id, last_message, state, context, created_at, updated_at
      FROM care_sessions
      WHERE global_user_id = $1
      ORDER BY updated_at DESC
      LIMIT $2 OFFSET $3
      `,
      [globalUserId, limit, offset]
    );

    // Contar total
    const countRow = await runQueryWithTenant<{ total: string }>(
      tenantId,
      `
      SELECT COUNT(*) as total
      FROM care_sessions
      WHERE global_user_id = $1
      `,
      [globalUserId]
    );

    return {
      rows,
      total: countRow ? Number(countRow.total) : 0,
    };
  }
}
















